cmd:
cat > /app/nginx-git-deploy.conf << 'EOF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name localhost;

    ssl_certificate /etc/nginx/ssl/server.crt;
    ssl_certificate_key /etc/nginx/ssl/server.key;

    root /var/www/main;
    index index.html;

    location /dev/ {
        root /var/www/dev;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
cp /app/nginx-git-deploy.conf /etc/nginx/sites-available/git-deploy && ln -sf /etc/nginx/sites-available/git-deploy /etc/nginx/sites-enabled/git-deploy && nginx -t 2>&1
